// THE mirror-clamp population source. The LAND is on every phase of every board (boards.tsx passes
// `mirrorClamp` to ViennaPhase unconditionally: one PCB, four SKUs); WHICH SKUs are POPULATED lives here
// and nowhere else, and the per-part qtyMul entries above are derived from it below. Every consumer — the
// BOM, the DPT deck's drawn() network, a DFM sheet — reads this.
// STANDING BOM NOTE for the DNP SKUs: fit the mirrored clamp if T-59 measures the unclamped negative
// half-cycle above 85 % of 750 V — +₹471/module (3 phases × [SiC JBS ₹55 + 100 nF/250 V film ₹18 + 470 Ω
// 10 W bleeder ₹22] at the 1k basis). At the 5 nH loop the DPT reads 76–79 % on 30/40 kW and 82 % on both
// 50 kW SKUs, which is why only the 50s are populated.
export const MIRROR_CLAMP = { "30kw": false, "40kw": false, "50kw": true, "50kwa": true };
// DC-DC entry film count per SKU: 16 × 1 µF/1100 V holds the 30/40 kW cans at 58/68 % of the RFQ ripple
// line at the 40 nH design stud; the 50 kW pair reads 81 % at 16 and needs 20 (+₹218). boards.tsx draws
// this count and the dclink deck / current-coordination gate it; the 20-film variant on 30/40 kW is the
// registered lever if T-57 measures ≤ 25 nH.
export const ENTRY_FILM = { "30kw": 16, "40kw": 16, "50kw": 20, "50kwa": 20 };
for (const [sku, fit] of Object.entries(MIRROR_CLAMP)) {
  if (fit || !skuOverrides[sku]) continue;
  for (const ph of ["A", "B", "C"]) for (const pre of ["D", "C", "R"]) {
    const ref = `${pre}${ph}0CM`;
    skuOverrides[sku][ref] = { ...(skuOverrides[sku][ref] ?? {}), qtyMul: 0 };
  }
}
skuOverrides["50kwa"] = { ...skuOverrides["50kw"] };   // air-50 shares every class part with the liquid

